How can we optimize energy consumption in a household using C++ code? Please provide a detailed strategy using the following C++ code as a reference:
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
int main() {
  // Load energy consumption data
  vector<double> energy_data = {2.3, 4.5, 3.2, 5.6, 4.1, 2.8, 3.9, 6.5, 4.3, 5.1, 3.7, 4.9, 5.3, 3.6, 2.7, 4.8, 3.1, 5.2, 4.4, 6.1, 3.8, 5.7, 2.9, 4.2, 6.2, 3.5, 5.9, 4.7, 2.6, 3.3, 5.4, 4.6, 3.4, 2.4, 6.3, 4.0, 5.5, 2.5, 6.4, 3.0};

  // Calculate daily energy consumption
  vector<double> daily_energy;
  for (int i = 0; i < energy_data.size(); i += 24) {
    double total = 0;
    for (int j = i; j < i + 24 && j < energy_data.size(); j++) {
      total += energy_data[j];
    }
    daily_energy.push_back(total);
  }

  // Sort daily energy consumption in ascending order
  sort(daily_energy.begin(), daily_energy.end());

  // Identify days with high energy consumption
  vector<double> high_energy;
  for (int i = 0; i < daily_energy.size(); i++) {
    if (daily_energy[i] > daily_energy[daily_energy.size() * 0.95]) {
      high_energy.push_back(daily_energy[i]);
    }
  }

  // Output results
  cout << "Days with high energy consumption: ";
  for (int i = 0; i < high_energy.size(); i++) {
    cout << high_energy[i] << " ";
  }
  cout << endl;

  return 0;
}

