```
using System;
public class MetalPlateTranslator {
    public static void Main(string[] args) {
        string metalPlateSymbols = "G#%@^&*()_+";
        string translatedMessage = Translate(metalPlateSymbols);
        Console.WriteLine(translatedMessage);
    }
    public static string Translate(string symbols) {
        string message = "";
        foreach (char symbol in symbols) {
            switch (symbol) {
                case 'G':
                    message += "Hello ";
                    break;
                case '#':
                    message += "world ";
                    break;
                case '%':
                    message += "how ";
                    break;
                case '@':
