Sure, I can provide an example of a class that simulates the behavior of a crowd at a concert using C++ and multi-threading to improve performance. 
The Crowd class would have the following properties:
- `num_people`: the total number of people in the crowd
- `x_positions`: an array of the x-coordinates of each person in the crowd
- `y_positions`: an array of the y-coordinates of each person in the crowd
- `velocities`: an array of the velocities of each person in the crowd
- `max_velocity`: the maximum velocity of any person in the crowd
- `min_distance`: the minimum distance that any two people in the crowd can be from each other
- `width` and `height`: the dimensions of the concert space
The class would have the following methods:
- `Crowd(num_people, width, height)`: constructor that initializes the `x_positions`, `y_positions`, and `velocities` arrays with random values
- `void move()`: updates the positions of each person in the crowd based on their current velocity
- `void update_velocities()`: updates the velocities of each person in the crowd based on their current positions and velocities of nearby people
- `void draw()`: draws the current state of the crowd on the screen
To improve performance, we can use multi-threading to update the positions and velocities of each person in the crowd simultaneously. We can create two separate threads, one for updating the positions and one for updating the velocities. 
Here's the relevant code snippets:
```c++
#include <iostream>
#include <thread>
#include <vector>
#include <cmath>
#include <cstdlib>
class Crowd {
public:
    Crowd(int num_people, int width, int height) : num_people(num_people), width(width), height(height) {
        x_positions.resize(num_people);
        y_positions.resize(num_people);
        velocities.resize(num_people);
        max_velocity = 5;
        min_distance = 10;
        for (int i = 0; i < num_people; i++) {
            x_positions[i] = rand() % width;
            y_positions[i] = rand() % height;
            velocities[i] = rand() % max_velocity;
        }
    }
    void move() {
        for (int i = 0; i < num_people; i++) {
            x_positions[i] += velocities[i];
            if (x_positions[i] < 0) {
                x_positions[i] = width;
            } else if (x_positions[i] > width) {
                x_positions[i] = 0;
            }
            y_positions[i] += velocities[i];
            if (y_positions[i] < 0) {
                y_positions[i] = height;
            } else if (y_positions[i] > height) {
                y_positions[i] = 0;
            }
        }
    }
    void update_velocities() {
        for (int i = 0; i < num_people; i++) {
            double avg_velocity = 0;
            int num_nearby = 0;
            for (int j = 0; j < num_people; j++) {
                if (i != j) {
                    double distance = sqrt(pow(x_positions[i] - x_positions[j], 2) + pow(y_positions[i] - y_positions[j], 2));
                    if (distance < min_distance) {
                        avg_velocity += velocities[j];
                        num_nearby++;
                    }
                }
            }
            if (num_nearby > 0) {
                avg_velocity /= num_nearby;
                if (avg_velocity > velocities[i]) {
                    velocities[i] += 1;
                } else if (avg_velocity < velocities[i]) {
                    velocities[i] -= 1;
                }
            }
        }
    }
    void draw() {
        // code to draw the crowd on the screen
    }
private:
    int num_people;
    std::vector<int> x_positions;
    std::vector<int> y_positions;
    std::vector<int> velocities;
    int max_velocity;
    int min_distance;
    int width;
    int height;
};
int main() {
    Crowd crowd(100, 800, 600);
    std::thread move_thread([&]() {
        while (true) {
            crowd.move();
        }
    });
    std::thread update_thread([&]() {
        while (true) {
            crowd.update_velocities();
        }
    });
    while (true) {
        crowd.draw();
    }
    return 0;
}
```
In the main function, we create a `Crowd` object with 100 people and a concert space with dimensions of 800x600. We then create two threads, one for updating the positions of each person in the crowd and one for updating the velocities of each person. Finally, we run an infinite loop to draw the current state of the crowd on the screen.
By using multi-threading, we can update the positions and velocities of each person in the crowd simultaneously, which improves the performance of the simulation.

