        $output += ($data["field"] + $data["impact"]);
    } elseif ($data["operation"] == "-") {
        $output -= ($data["field"] - $data["impact"]);
    } elseif ($data["operation"] == "/") {
        $output /= ($data["field"] / $data["impact"]);
    }
}
// Display the results in a table
echo "<table>";
echo "<tr><th>Scientist</th><th>Field of Study</th><th>Impact on Modern Science</th></tr>";
foreach ($scientists as $scientist => $data) {
    echo "<tr><td>$scientist</td><td>{$data['field']}</td><td>{$data['impact']}</td></tr>";
}
echo "<tr><td><strong>Total</strong></td><td></td><td>$output</td></tr>";
echo "</table>";
?>
