		if err != nil {
			log.Fatal(err)
		}
		if len(tweets) == 0 {
			break
		}
		allTweets = append(allTweets, tweets...)
		params.MaxID = tweets[len(tweets)-1].ID - 1 // get tweets older than the last one
	}
	// Analyze tweets
