How can I categorize a given sound into either animal, human, or non-living using C++ code?
For example, if the sound is "barking," how can I write a C++ code to categorize it as an animal sound?
Here's a sample C++ code that can categorize sounds based on keywords:
#include <iostream>
#include <string>
#include <vector>
using namespace std;
vector<string> animalSounds = {"barking", "meowing", "roaring", "howling"};
vector<string> humanSounds = {"talking", "singing", "laughing", "crying"};
vector<string> nonLivingSounds = {"beeping", "ringing", "whistling", "buzzing"};
bool isAnimalSound(string sound) {
    for (string animalSound : animalSounds) {
        if (sound.find(animalSound) != string::npos) {
            return true;
        }
    }
    return false;
}
bool isHumanSound(string sound) {
    for (string humanSound : humanSounds) {
        if (sound.find(humanSound) != string::npos) {
            return true;
        }
    }
    return false;
}
bool isNonLivingSound(string sound) {
    for (string nonLivingSound : nonLivingSounds) {
        if (sound.find(nonLivingSound) != string::npos) {
            return true;
        }
    }
    return false;
}
int main() {
    string sound = "barking";
    if (isAnimalSound(sound)) {
        cout << sound << " is an animal sound." << endl;
    } else if (isHumanSound(sound)) {
        cout << sound << " is a human sound." << endl;
    } else if (isNonLivingSound(sound)) {
        cout << sound << " is a non-living sound." << endl;
    } else {
        cout << sound << " is an unknown sound." << endl;
    }
    return 0;
}
In this code, the sounds are categorized based on keywords stored in three separate vectors. The isAnimalSound(), isHumanSound(), and isNonLivingSound() functions check if a given sound contains any of the keywords in their respective vectors. The main() function simply calls these functions and prints the appropriate message based on the category of the sound.

