To retrieve information about penguins and their mating habits in C# code, you can use an API or web scraping techniques to fetch data from online sources such as Wikipedia or National Geographic. Here's an example using the Wikipedia API:
```csharp
using System;
using System.Net.Http;
using System.Text.Json;
using System.Threading.Tasks;
class Program
{
    static async Task Main(string[] args)
    {
        // Set up HTTP client and request parameters
        var client = new HttpClient();
        var url = "https://en.wikipedia.org/w/api.php?action=query&format=json&prop=extracts&titles=Penguin&exintro=1&explaintext=1";
        var response = await client.GetAsync(url);
        response.EnsureSuccessStatusCode();
        // Parse JSON response and extract information about penguins
        var json = await response.Content.ReadAsStringAsync();
        var data = JsonSerializer.Deserialize<RootObject>(json);
        var extract = data.query.pages[0].extract;
        // Print out some facts about penguins
        Console.WriteLine(extract);
        Console.WriteLine("\nHere are some facts about penguins:");
        Console.WriteLine("- Penguins are flightless birds that live in the Southern Hemisphere.");
        Console.WriteLine("- There are 18 species of penguins, ranging in size from the tiny fairy penguin to the emperor penguin, which can grow up to 4 feet tall.");
        Console.WriteLine("- During mating season, male and female penguins take turns incubating their eggs, with the male typically taking the first shift.");
        // Wait for user input before exiting
        Console.ReadLine();
    }
    public class RootObject
    {
        public Query query { get; set; }
    }
    public class Query
    {
        public Page[] pages { get; set; }
    }
    public class Page
    {
        public string extract { get; set; }
    }
}
```
