```c++
#include <iostream>
#include <unordered_map>
#include <string>
#include <algorithm>
using namespace std;
int main()
{
    string sentence = "the quick brown fox jumps over the lazy dog";

    // Convert all characters to lowercase to avoid case sensitivity
    transform(sentence.begin(), sentence.end(), sentence.begin(), ::tolower);

    // Initialize an unordered map to store word frequencies
    unordered_map<string, int> wordFreq;

    // Extract each word from the sentence and update its frequency in the map
    string word = "";
    for (char c : sentence) {
        if (c == ' ') {
            wordFreq[word]++;
            word = "";
        } else {
            word += c;
        }
    }
    wordFreq[word]++; // Add the last word

    // Print the table of word frequencies
    cout << "Word\tFrequency" << endl;
    for (auto const& pair : wordFreq) {
        cout << pair.first << "\t" << pair.second << endl;
    }

    return 0;
}
```
