Here is the MATLAB code that implements Merge Sort algorithm:
```
function sorted_list = merge_sort(list)
% Check if the list has only one element
if length(list) <= 1
    sorted_list = list;
    return
end
% Split the list into two halves
mid = floor(length(list)/2);
left_half = list(1:mid);
right_half = list(mid+1:end);
% Recursively sort the two halves
left_sorted = merge_sort(left_half);
right_sorted = merge_sort(right_half);
% Merge the two sorted halves
sorted_list = merge(left_sorted, right_sorted);
end
function merged_list = merge(left, right)
% Initialize pointers for left and right lists
i = 1;
j = 1;
% Initialize merged list
merged_list = [];
% Merge the two lists while preserving order of repeated elements
while i <= length(left) && j <= length(right)
    if left(i) <= right(j)
        merged_list = [merged_list, left(i)];
        i = i + 1;
    else
        merged_list = [merged_list, right(j)];
        j = j + 1;
    end
end
% Append any remaining elements from left or right list
if i <= length(left)
    merged_list = [merged_list, left(i:end)];
elseif j <= length(right)
    merged_list = [merged_list, right(j:end)];
end
end
```
To sort the list [5, 2, 5, 1, 7, 2], you can call the function like this:
```
list = [5, 2, 5, 1, 7, 2];
sorted_list = merge_sort(list);
disp(sorted_list);
```
This code will output the sorted list: [1, 2, 2, 5, 5, 7]. 
Note that Merge Sort has a worst-case time complexity of O(nlogn) and uses minimal memory because it sorts the list by dividing it into smaller sub-lists and sorting them separately before merging them back together.

